package com.company.platform.aigateway.orchestration;import java.util.*;import org.springframework.stereotype.Component;@Component public class PromptVersionManager{private final Map<String,NavigableMap<Integer,Map<String,Object>>> versions=new HashMap<>();public Map<String,Object> register(String key,int version,String classification){Map<String,Object>x=Map.of("key",key,"version",version,"classification",classification,"active",false);versions.computeIfAbsent(key,k->new TreeMap<>()).put(version,x);return x;}public Optional<Map<String,Object>> current(String key){var x=versions.get(key);return x==null?Optional.empty():x.descendingMap().values().stream().findFirst();}}
